use std::path::Path;
use std::process::ExitCode;

use clap::{CommandFactory, FromArgMatches, Parser, Subcommand};
use clap_complete::CompleteEnv;
use log::error;

use crate::subcommand::SubcommandRunner;

/// Name this invocation was launched under: `argv[0]`'s basename,
/// falling back to the compiled bin name when argv is empty or
/// unreadable. Runtime on purpose: the binary's on-disk name is
/// the manifest's per-line package name, and a copy or rename
/// afterwards still self-reports the name it actually runs as,
/// which no compile-time constant can know.
fn invoked_name() -> String {
    std::env::args_os()
        .next()
        .as_deref()
        .and_then(|p| Path::new(p).file_name())
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| env!("CARGO_BIN_NAME").to_string())
}

/// Banner string emitted as the first line of every run (stderr,
/// or stdout when `-V` asked for it), and shown at the top of
/// subcommand `--help` output: `<invoked name> <version>`, the
/// version carrying `+<commit>` when the build knew its commit.
fn banner() -> &'static str {
    static BANNER: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    BANNER.get_or_init(|| {
        format!(
            "{} {}{}",
            invoked_name(),
            env!("CARGO_PKG_VERSION"),
            version::build_metadata()
        )
    })
}

/// The banner a run prints: the plain banner plus the workspace's
/// set version, ` (agent-files v0.1.0)`, when the current directory
/// is in a workspace that records one. Help keeps the plain banner,
/// since help is not a run and its text must not depend on the cwd.
fn run_banner() -> String {
    let root = common::find_workspace_root();
    format!(
        "{}{}",
        banner(),
        agent_files::banner_suffix(root.as_deref())
    )
}

/// Top-level about line: name, version, and the project tagline
/// on a single line. Used as the top-level `about` so `vc-x1 -h`
/// reads as one banner-plus-tagline header instead of two stacked
/// lines.
fn top_about() -> String {
    format!("{} - jj workspace tooling", banner())
}

/// Build the clap command tree with `BANNER` set as `before_help`
/// on every subcommand (transitively). Top-level skips `before_help`
/// because its own `about` already carries the name+version+tagline.
/// Walks via `mut_subcommand` so individual subcommand
/// `#[command(long_about = ...)]` blocks don't have to repeat the
/// banner text.
fn cli_with_banner() -> clap::Command {
    fn add_to_subs(mut cmd: clap::Command) -> clap::Command {
        let names: Vec<String> = cmd
            .get_subcommands()
            .map(|c| c.get_name().to_string())
            .collect();
        for name in names {
            cmd = cmd.mut_subcommand(name, add_with_banner);
        }
        cmd
    }
    fn add_with_banner(mut cmd: clap::Command) -> clap::Command {
        cmd = cmd.before_help(banner());
        let names: Vec<String> = cmd
            .get_subcommands()
            .map(|c| c.get_name().to_string())
            .collect();
        for name in names {
            cmd = cmd.mut_subcommand(name, add_with_banner);
        }
        cmd
    }
    // `bin_name` from the invoked name: `get_matches` would set it
    // from argv itself, but the manual `print_help` on the
    // no-subcommand path never sees argv and would fall back to
    // the package name, printing `Usage: vc-x1` under vc-x1-dev.
    add_to_subs(Cli::command().bin_name(invoked_name()))
}

#[derive(Parser, Debug)]
#[command(about = top_about(), max_term_width = 80)]
pub struct Cli {
    /// Version detail on stdout: -V the banner, -VV the full
    /// report (as `vc-x1 version`). Counted like -v/-vv.
    ///
    /// Both ride along: they print, then the subcommand runs, so
    /// one invocation captures the version and the command's
    /// output together. That is why this replaces clap's
    /// auto-version, which would exit after printing. Without
    /// either, the banner still prints, on stderr.
    #[arg(short = 'V', long = "version", global = true, action = clap::ArgAction::Count)]
    pub version: u8,

    /// Suppress the banner stderr normally carries on every run.
    ///
    /// Only the ambient banner: an explicit `-V` still prints,
    /// since asking for it outranks suppressing it.
    #[arg(long = "no-banner", global = true, action = clap::ArgAction::SetTrue)]
    pub no_banner: bool,

    /// Run even when `jj -V` disagrees with our linked jj-lib.
    ///
    /// Per-invocation on purpose, never a config key: a key gets
    /// set once during a frustrating afternoon and then silently
    /// protects nothing.
    #[arg(long = "allow-jj-mismatch", global = true, action = clap::ArgAction::SetTrue)]
    pub allow_jj_mismatch: bool,

    /// Verbose output: -v debug, -vv trace
    #[arg(short, long, global = true, action = clap::ArgAction::Count)]
    pub verbose: u8,

    /// Log file path (captures all levels)
    #[arg(long, global = true)]
    pub log: Option<std::path::PathBuf>,

    #[command(subcommand)]
    pub(crate) command: Option<Commands>,
}

#[derive(Subcommand, Debug)]
pub(crate) enum Commands {
    /// The agent-files set: its version, and a diff against a copy of it
    #[command(name = "agent-files")]
    AgentFiles(agent_files::AgentFilesArgs),

    /// Print vc-x1, jj-lib, and jj-data versions
    #[command(
        long_about = "Print every version that describes this run: vc-x1's own,\n\
        the jj-lib it links against, and what each repo's jj data\n\
        records about itself.\n\n\
        The jj-data lines are backend type names, not versions:\n\
        jj records no format version we can read."
    )]
    Version,

    /// Print the changeID for a revision
    Chid(chid::ChidArgs),

    /// Show full description of a commit
    Desc(desc::DescArgs),

    /// List commits in a jj repo
    List(list::ListArgs),

    /// Show commit details and diff summary
    Show(show::ShowArgs),

    /// Working-copy status and clean verdict, by scope (alias st)
    #[command(
        name = "status",
        alias = "st",
        long_about = "Print the working-copy status of the scoped repos, each\n\
        under its label with the changed paths and the @ and @- lines as\n\
        `jj st` prints them, then one verdict line: `clean` when every\n\
        scoped @ is empty and undescribed, At rest's meaning of the word\n\
        for `both`, else `dirty` naming each repo and why.\n\n\
        -s takes the write commands' four scopes, `w|work`, `a|agent`,\n\
        `b|both`, or `p|por` for a plain repo, and is `work` when absent.\n\
        A plain jj repo with no vc-x1 config also answers for `work`."
    )]
    Status(status::StatusArgs),

    /// Show the lines in the other repo that a line in this one relates to
    #[command(
        long_about = "Resolve a line in either repo of a dual workspace to the\n\
        window of lines in the other repo.\n\n\
        `lookup [-s SCOPE] --line FILE:LINE`: SCOPE is the side the line\n\
        is on, `work` or `agent`, and FILE:LINE is the form editors,\n\
        compilers, and grep print. SCOPE is inferred from the file's path\n\
        when omitted, and with SCOPE given a path relative to that side's\n\
        repo root works from anywhere. A named SCOPE the path disagrees\n\
        with is an error. The line must exist in the file on disk. Every\n\
        argument is a flag: the old `[SCOPE] FILE:LINE` positionals are\n\
        refused, naming -s and --line."
    )]
    Lookup(lookup::LookupArgs),

    /// Display an agent session transcript as a conversation
    #[command(
        name = "agent-session",
        long_about = "Display a Claude Code agent session transcript (.jsonl) as a\n\
        readable conversation.\n\n\
        Output is a set of items (headers, user, assistant, tool,\n\
        thinking, results, meta, summary) each toggled by --<item> /\n\
        --no-<item> (last one wins), with --all / --none as bulk bases.\n\
        The default set (headers, user, assistant, tool, summary) can\n\
        be replaced by [agent-session].items in the user config\n\
        (comma-separated list); CLI flags then adjust the resolved\n\
        set. Malformed lines (e.g. a live session's truncated last\n\
        line) warn to stderr and never fail the run.\n\n\
        Alternate views: --fields (field inventory per entry type),\n\
        --unknown (only unmodeled paths: how the format moved), and\n\
        --raw (pretty-printed source lines). --lines slices by source\n\
        JSONL line: the same unit in every view."
    )]
    BotSession(bot_session::BotSessionArgs),

    /// Rejected pre-0.80.0 name of `agent-session`: prints the fix-it
    /// and exits non-zero, for any flags.
    #[command(name = "bot-session", hide = true, disable_help_flag = true)]
    BotSessionOld {
        /// Swallowed so the fix-it shows for any invocation.
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 0..)]
        rest: Vec<String>,
    },

    /// Run the workspace's configured validation commands
    #[command(long_about = "Run the workspace's configured validation commands.\n\n\
        Reads `[validate] full` (or `fast` with --fast) from the work\n\
        side's config and runs each element as one command, in order,\n\
        from the work repo root, printing each before it runs. The\n\
        first failure stops the run, naming the command and its exit\n\
        status, and the subcommand exits non-zero. An empty or missing\n\
        table is an error, not a pass. See `vc-x1 config -s work` for the\n\
        table's shape.")]
    Validate(validate::ValidateArgs),

    /// Build the chosen profile, off the PATH
    #[command(long_about = "Build the chosen profile, off the PATH.\n\n\
        A profile is a `[profile.<NAME>]` table, chosen by --profile NAME,\n\
        else `[build] default-profile`, else release. Runs `[build] commands`\n\
        from the work repo root, here\n\
        `cargo build --profile {profile.cargo} --locked`, each\n\
        {profile.<property>} filled from the profile and a list-valued one,\n\
        such as {profile.flags}, filling a word per item, and checks it left\n\
        the profile's `bin`, the binary the config says the build leaves.\n\
        The commands see the commit `@-` and the state of the source code,\n\
        clean when `@` was empty and dirty when not, as VC_X1_BUILD_COMMIT\n\
        and VC_X1_BUILD_STATE, as validate's do, so vc-x1's\n\
        own banner carries the commit. Cargo decides what to rebuild, so a\n\
        build with nothing changed is quick. A build is run by `vc-x1 run`\n\
        and copied into the install directory by `vc-x1 install`, which run\n\
        this same build first.\n\n\
        Nothing is checked first: a release may be built from a cycle's\n\
        bookmark to try the release profile. The list runs as `validate`'s\n\
        does, each element one command, the first failure stopping the run.\n\
        --dry-run prints the list and runs nothing. See `vc-x1 config -s work`\n\
        for the keys.\n\n\
        --profile dev builds this workspace's dev profile, leaving\n\
        `target/debug/vc-x1`. After a validation it reuses the test build,\n\
        so it takes under a second. The old `build-dev` and `build --dev`\n\
        are refused, naming `build --profile dev`.")]
    Build(build_cmd::BuildArgs),

    /// Retired: `build-dev`, now `build --profile dev`, refused naming it
    #[command(hide = true)]
    BuildDev(build_cmd::BuildDevArgs),

    /// Build the chosen profile if out of date, then copy it into the install directory
    #[command(
        long_about = "Build the chosen profile if out of date, then copy it into the install\n\
        directory.\n\n\
        The profile is --profile NAME, else `[build] default-profile`, else\n\
        release. It first runs `[build] commands`, exactly as `vc-x1 build`\n\
        does. Cargo rebuilds only what changed, so with nothing changed\n\
        the binary already tested is the one copied. The build leaves the\n\
        profile's `bin` (here `target/release/vc-x1` for release), and\n\
        `install` copies it into the one directory `[install] dir` names\n\
        (here `~/.cargo/bin`, `~` expanded), under the same file name with\n\
        the profile's `suffix` appended (here `vc-x1-dev` for dev), so the\n\
        profiles sit side by side on the PATH. A copy that would land on\n\
        another profile's destination is refused before the build.\n\
        It does not search $PATH. The copy goes to a temporary file renamed\n\
        into place, so a running copy of the old binary is undisturbed and a\n\
        failed copy leaves the old one. An `[install] commands` list, when\n\
        present, runs in place of the copy, each word's {profile.<property>}\n\
        and {install.dir} filled with the values resolved for the run,\n\
        --dir applied, so the list names every path it writes. This\n\
        workspace's list is the copy written out.\n\n\
        Before copying it reports what it is copying: the version and commit\n\
        the binary's -V shows, whether that commit is `main` and\n\
        `main@origin`, clean or dirty, and a version with a cycle's suffix.\n\
        A binary whose -V carries no commit is reported as unknown. The\n\
        report is for you to judge, and refuses nothing: which builds may be\n\
        installed is the release process's call, not the tool's. It refuses\n\
        only when the copy itself would be wrong: no binary at the profile's\n\
        `bin` after the build, a binary whose -V will not run, or a missing\n\
        install directory. --dry-run builds and reports, and copies nothing.\n\
        --dir DIR copies into DIR instead of `[install] dir` for this run, so\n\
        a test of install leaves the PATH alone, a relative DIR taken\n\
        against the current directory. A workspace with no `[install] dir`\n\
        and no --dir has nothing to install, and builds nothing.\n\n\
        The old `install-dev` and `install --dev` are refused, naming\n\
        `install --profile dev`."
    )]
    Install(install_cmd::InstallArgs),

    /// Retired: `install-dev`, now `install --profile dev`, refused naming it
    #[command(hide = true)]
    InstallDev(install_cmd::InstallDevArgs),

    /// Build the chosen profile, then run it with the given arguments
    #[command(
        long_about = "Build the chosen profile, then run it with the given arguments.\n\n\
        The profile is --profile NAME, given before the arguments, else\n\
        `[build] default-profile`, else release. It first runs\n\
        `[build] commands`, exactly as `vc-x1 build` does, then runs the\n\
        profile's `bin` (here `target/release/vc-x1` for release) in the\n\
        current directory, as `cargo run` builds before it runs, so what\n\
        runs is always the current code. The arguments go to the binary\n\
        untouched. One that starts with `-` comes after --, as with cargo\n\
        run, since vc-x1's own flags are read first: `vc-x1 run -- -V` is\n\
        the smoke check before install, and `vc-x1 run --profile dev -- -V`\n\
        the dev build's. The binary's exit code is vc-x1's.\n\n\
        Its -V is read first, and a version other than the manifest's is a\n\
        warning naming the profile's `bin`. --dry-run prints the build's list\n\
        and the command, and runs nothing. Completion of the arguments is\n\
        the binary's own, asked in clap's completion mode and never built.\n\n\
        The old `run-dev` and `run --dev` are refused, naming\n\
        `run --profile dev`."
    )]
    Run(run_cmd::RunArgs),

    /// Retired: `run-dev`, now `run --profile dev`, refused naming it
    #[command(hide = true)]
    RunDev(run_cmd::RunDevArgs),

    /// Check the agent repo is published (main matches main@origin)
    #[command(
        name = "validate-agent",
        long_about = "Check the agent repo is published (main matches main@origin).\n\n\
        At rest the agent repo's `main` always matches `main@origin`: the\n\
        bookmark only moves inside a push / squash-push run, which\n\
        publishes it in the same invocation. A mismatch means an earlier\n\
        publish was lost. Read-only and cheap (two jj lookups; no cargo\n\
        steps); also verifies main's remote refs are tracked. Exits\n\
        non-zero on any finding and fixes nothing: resolve with\n\
        `vc-x1 squash-push -s a`."
    )]
    ValidateBot(validate_bot::ValidateBotArgs),

    /// Rejected pre-0.80.0 name of `validate-agent`: prints the fix-it
    /// and exits non-zero, for any flags.
    #[command(name = "validate-bot", hide = true, disable_help_flag = true)]
    ValidateBotOld {
        /// Swallowed so the fix-it shows for any invocation.
        #[arg(trailing_var_arg = true, allow_hyphen_values = true, num_args = 0..)]
        rest: Vec<String>,
    },

    /// Validate commit descriptions against the other repo
    #[command(
        long_about = "Validate commit descriptions against the other repo.\n\n\
        Output columns: STATUS  CHANGEID  TITLE  [DETAILS]\n\n\
        Status labels:\n  \
          ok   : ochid trailer is valid\n  \
          err  : ochid has issues (wrong prefix, wrong length, ID not found), or\n         \
          an orepo names the wrong repo\n  \
          note : ok, with something worth saying, an agent commit not yet pushed\n  \
          miss : no ochid trailer; shows match from other repo if found"
    )]
    ValidateDesc(validate_desc::ValidateDescArgs),

    /// Fix commit descriptions against the other repo (dry-run by default)
    #[command(long_about = "Fix commit descriptions against the other repo.\n\n\
        Default is dry-run; use --no-dry-run to write changes.\n\n\
        Output columns: STATUS  CHANGEID  TITLE  [DETAILS]\n\n\
        Status labels:\n  \
          ok    : ochid trailer is valid (no change)\n  \
          fix   : ochid has issues, shows proposed fix (dry-run)\n  \
          fixed : ochid was rewritten (--no-dry-run)\n  \
          add   : missing ochid, match found, shows proposed addition (dry-run)\n  \
          added : missing ochid was added (--no-dry-run)\n  \
          skip  : skipped (no ochid, no match, or max-fixes reached)\n  \
          err   : ID not found and no --fallback provided")]
    FixDesc(fix_desc::FixDescArgs),

    /// Check the workspace's config files
    #[command(long_about = "Check a workspace's config files.\n\n\
        Verifies every key is one the schema declares for that side,\n\
        the legacy schema is rejected, a dual workspace's two [repos]\n\
        registries agree, the file's own links resolve, and a side's\n\
        config carries `repos.work`. Read-only; exits non-zero when\n\
        anything is found. Was `config --validate` before 0.80.6.")]
    ValidateConfig(validate_config::ValidateConfigArgs),

    /// Check a markdown record's own anchors and references
    #[command(long_about = "Check a markdown file's same-file links.\n\n\
        Verifies every `](#slug)` link and `[N]: #slug` definition\n\
        resolves to a heading in the same file, every `[[N]]` citation\n\
        has a definition and every definition is cited, and no two\n\
        headings slug to one anchor. Cross-file targets are skipped.\n\
        Read-only; exits non-zero when anything is found. With no\n\
        FILE, checks every `.md` in the workspace.")]
    ValidateAnchors(validate_anchors::ValidateAnchorsArgs),

    /// Check todo-file entry numbering and indent
    #[command(
        long_about = "Check a todo file's `## Todo` and `## Bugs` entry numbering.\n\n\
        Verifies each section is numbered 1..N in document order and\n\
        that continuation-line indent matches the number-prefix width.\n\
        Read-only; exits non-zero if any entry needs fixing: use\n\
        `fix-todo` to rewrite."
    )]
    ValidateTodo(validate_todo::ValidateTodoArgs),

    /// Renumber todo-file entries (dry-run by default)
    #[command(
        long_about = "Renumber a todo file's `## Todo` and `## Bugs` sections.\n\n\
        Renumbers each section 1..N in document order and normalizes\n\
        continuation-line indent to the number-prefix width. Dry-run\n\
        by default: prints each changed entry's corrected line; pass\n\
        --no-dry-run to write the file in place."
    )]
    FixTodo(fix_todo::FixTodoArgs),

    /// Clone a project, a dual workspace or a plain repo with -s por
    Clone(clone::CloneArgs),

    /// Create a project, a dual workspace or a plain repo with -s por
    Init(init::InitArgs),

    /// Create Claude Code project symlink
    Symlink(symlink::SymlinkArgs),

    /// Fetch and sync a set of repos to their remotes
    #[command(long_about = format!("Fetch and sync a set of repos to their remotes.\n\n\
        Repo set is resolved (in order):\n  \
          - `-R` / `--repo`     exact list (back-compat / arbitrary multi-repo)\n  \
          - `--scope=work|agent|work,agent` dual-repo roles via `.vc-config.toml`\n  \
          - neither             `.`, the one repo sync is run in\n\n\
        Safe by default: before it fetches, sync finds out what the\n\
        fetch would do. It asks the remote where its bookmarks are,\n\
        downloads the commits of those that moved without moving a\n\
        ref, and tells a fast-forward from a rewrite. Then:\n  \
          - remote has not moved   nothing to fetch\n  \
          - only fast-forwarded    fetch; local work is left untouched\n  \
          - would tangle           held back; sync says why, exits non-zero\n\
        A fetch would tangle local work when a bookmark that moved has\n\
        local commits of its own, or when the remote rewrote a\n\
        bookmark and the repo holds local work: uncommitted changes in\n\
        `@` (not asked of the agent repo, whose `@` holds the running\n\
        session), an `@-` that is not on the remote, or a bookmark\n\
        with commits the remote does not have. --force, or --rebase,\n\
        syncs a repo that would be held back.\n\n\
        With --dry-run sync does the same finding out and stops: it\n\
        reports each repo's state, its local work, and what a sync\n\
        would do, and moves no bookmark, `@`, or remote-tracking ref.\n\
        It exits 0 whatever it finds.\n\n\
        One atomic operation: fetch, then per repo, by where its\n\
        bookmark was before the fetch:\n  \
          - up-to-date        nothing to do\n  \
          - behind            fast-forward bookmark to remote\n  \
          - rewritten         the remote replaced the commit; fetch followed it\n  \
          - ahead             nothing to sync\n  \
          - diverged          --force only: rebase onto remote, fail on conflicts\n  \
          - no remote         bookmark has no @<remote> counterpart; skip\n\n\
        After a successful sync, `@` is repositioned onto the synced\n\
        bookmark: the work repo `jj new`s a clean `@` (or with\n\
        --force rebases a dirty one), the `.claude` session repo\n\
        `jj new main`s when main moved (no-op when `@-` is already\n\
        the main tip).\n\n\
        On failure sync stops where the failing step stopped: nothing\n\
        is auto-reverted, so the state can be inspected. The failure\n\
        report prints each repo's pre-sync op id; undo explicitly with\n\
        `jj op restore <op> -R <repo>`. Nothing persists across\n\
        invocations.\n\n\
        Output shape:\n  \
          - all-up-to-date: one-line summary (`sync: N repos are {}`)\n  \
          - anything else:  per-repo fetch + state + actions\n  \
          - --quiet:        no output; exit code signals success", sync::UP_TO_DATE_MSG))]
    Sync(sync::SyncArgs),

    /// Squash SOURCE into TARGET, advance a bookmark, and push
    #[command(
        long_about = "Squash SOURCE into TARGET (defaults: SOURCE=@, TARGET=@-),\n\
        advance a bookmark, and push.\n\n\
        Captures a repo's trailing working-copy writes into the last\n\
        commit and publishes it. Built for the agent repo, the session\n\
        tail folded into the last agent commit after a session, so both\n\
        repos are clean: the change id folded into is kept, so the\n\
        `ochid:` naming it still resolves.\n\n\
        A push that would be forced, the target already on the\n\
        bookmark's remote or the remote not below it, asks before\n\
        anything changes, so a published commit is rewritten only by\n\
        choice. The --yes flag answers in advance, a configured\n\
        squash-push.yes never does, and without a tty and --yes it is\n\
        an error.\n\n\
        Zero-ceremony default: bare `vc-x1 squash-push` squashes\n\
        @ -> @- in `.` and pushes the bookmark of the line you are\n\
        on. With an empty `@` but work still to do, the squash is\n\
        skipped and the push still runs.\n\n\
        --bookmark defaults to the line's own bookmark, the nearest one\n\
        at or above the squash target, and there is no literal\n\
        default. On the agent repo that is `main`. On a work repo\n\
        running a cycle it is the topic bookmark, so a bare run\n\
        publishes the line you are working and never advances `main`.\n\
        Several candidates, or none, is an error asking you to name\n\
        one, since a wrong guess here publishes something. Every\n\
        argument is a flag: the old positional is refused, naming\n\
        --bookmark.\n\n\
        A precheck asks whether the run has work at all: the working\n\
        copy at rest, the bookmark at its origin, and the bookmark\n\
        already at the squash target. That third condition is there\n\
        because a bookmark behind its target has a commit to publish\n\
        even when it matches origin. A run with no work prints\n\
        `<label>: clean` and exits 0 having touched nothing, <label>\n\
        being the repo's directory name. Every other run prints the\n\
        same line after the push, as a report only: the exit code\n\
        says whether the push completed, not what that line found.\n\n\
        With work found, the run acts without asking, the default\n\
        `squash-push.yes` sets. --ask turns the prompt on for one run\n\
        and -y/--yes turns it off. With the prompt on, a non-tty run\n\
        is an error rather than a hang, and declining is an error too.\n\n\
        As `vc-x1 push`'s squash-push-bot stage it says nothing and\n\
        asks nothing, there being no one mid-push to read a line or\n\
        answer a prompt. The precheck's decision still applies, so a\n\
        stage with no work still does nothing."
    )]
    SquashPush(squash_push::SquashPushArgs),

    /// Print settable config keys and their defaults
