            Ok(_) => panic!("expected Open"),
            Err(e) => Err(e.to_string()),
        }
    }

    fn params(fx: &Fixture, args: &[&str]) -> OpenParams {
        let mut all = vec!["vc-x1", "open"];
        all.extend_from_slice(args);
