1	//! Shared core for the `validate-todo` / `fix-todo` subcommands:
2	//! parse `TODO.md`'s numbered sections and compute the
3	//! renumber / re-indent plan.
4	//!
5	//! - `## Todo` and `## Bugs` hold manually-numbered entries
6	//!   (`1.` `2.` ... at column 0); every other section is skipped.
7	//! - `analyze` walks the file once: it returns one `Change` per
8	//!   entry whose number or continuation indent is off, plus the
9	//!   fully renumbered / re-indented file content.
10	//! - Continuation indent is normalized against each entry's
11	//!   *measured* base indent, so nested `- ` sub-bullets keep
12	//!   their relative depth.
13	
14	/// Default todo file, relative to the workspace root.
15	pub const TODO_FILE: &str = "TODO.md";
16	
17	/// A manually-numbered section of the todo file.
18	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
19	pub enum Section {
20	    /// The `## Todo` backlog list.
21	    Todo,
22	    /// The `## Bugs` list.
23	    Bugs,
24	}
25	
26	impl Section {
27	    /// The section's markdown header text (`## Todo` / `## Bugs`).
28	    pub fn header(self) -> &'static str {
29	        match self {
30	            Section::Todo => "## Todo",
31	            Section::Bugs => "## Bugs",
32	        }
33	    }
34	}
35	
36	/// One entry whose number and/or continuation indent needs to
37	/// change for the section to be sequentially numbered.
38	///
39	/// - `num_old` / `num_new`: the displayed number and its
40	///   sequential (1-based) position; equal when only the indent is
41	///   off.
42	/// - `new_first_line`: the entry's first line with the corrected
43	///   number.
44	/// - `indent_old` / `indent_new`: the measured continuation-base
45	///   indent and the expected one (the number prefix's width);
46	///   both `None` when the entry has no continuation lines.
47	pub struct Change {
48	    pub section: Section,
49	    pub line_no: usize,
50	    pub new_first_line: String,
51	    pub num_old: usize,
52	    pub num_new: usize,
53	    pub indent_old: Option<usize>,
54	    pub indent_new: Option<usize>,
55	}
56	
57	/// Result of scanning a todo file: per-section entry counts, the
58	/// entries needing a fix, and the fully corrected file content.
59	pub struct Analysis {
60	    pub todo_count: usize,
61	    pub bugs_count: usize,
62	    pub changes: Vec<Change>,
63	    pub fixed: String,
64	}
65	
66	/// An entry being accumulated during the `analyze` walk: its
67	/// `N. ` number, that line minus its prefix, and the raw
68	/// continuation lines (blank lines included).
69	struct PendingEntry {
70	    section: Section,
71	    line_no: usize,
72	    num_old: usize,
73	    num_new: usize,
74	    rest: String,
75	    cont: Vec<String>,
76	}
77	
78	/// Number of decimal digits in `n` (entry numbers are >= 1).
79	fn digit_count(n: usize) -> usize {
80	    n.to_string().len()
81	}
82	
83	/// Count of leading ASCII spaces on `line`.
84	fn leading_spaces(line: &str) -> usize {
85	    line.len() - line.trim_start_matches(' ').len()
86	}
87	
88	/// Returns `entry` / `entries`: the count noun for `n`.
89	pub fn entry_word(n: usize) -> &'static str {
90	    if n == 1 { "entry" } else { "entries" }
91	}
92	
93	/// Build the `[line: ...]` tag for an entry: its line number,
94	/// then what changed (`was N`, `indent A -> B`, or both). Used by
95	/// `validate-todo` and `fix-todo` for the same per-entry line.
96	pub fn change_tag(c: &Change) -> String {
97	    let mut parts: Vec<String> = Vec::new();
98	    if c.num_old != c.num_new {
99	        parts.push(format!("was {}", c.num_old));
100	    }
101	    if let (Some(o), Some(n)) = (c.indent_old, c.indent_new)
102	        && o != n
103	    {
104	        parts.push(format!("indent {o} -> {n}"));
105	    }
106	    format!("[{}: {}]", c.line_no, parts.join(", "))
107	}
108	
109	/// Classify a line as a `## ` section header.
110	///
111	/// - `None`: not a level-2 header (covers `# `, `### `, body
112	///   text).
113	/// - `Some(None)`: a `## ` header that isn't `## Todo` /
114	///   `## Bugs` (e.g. `## In Progress`, `## Done`).
115	/// - `Some(Some(section))`: the `## Todo` or `## Bugs` header.
116	fn section_header(line: &str) -> Option<Option<Section>> {
117	    if !line.starts_with("## ") {
118	        return None;
119	    }
120	    Some(match line.trim_end() {
121	        "## Todo" => Some(Section::Todo),
122	        "## Bugs" => Some(Section::Bugs),
123	        _ => None,
124	    })
125	}
126	
127	/// Parse a leading `N. ` entry prefix at column 0.
128	///
129	/// Returns `(number, prefix_len)` (the entry number and the byte
130	/// length of the `N. ` prefix) when `line` begins with one or
131	/// more ASCII digits followed by `". "` (the renumber
132	/// convention's `^\d+\. ` anchor). Returns `None` for intro lines
133	/// (which carry a leading space), continuation lines, and
134	/// headings.
135	fn parse_entry_prefix(line: &str) -> Option<(usize, usize)> {
136	    let bytes = line.as_bytes();
137	    let mut i = 0;
138	    while i < bytes.len() && bytes[i].is_ascii_digit() {
139	        i += 1;
140	    }
141	    if i == 0 || bytes.get(i) != Some(&b'.') || bytes.get(i + 1) != Some(&b' ') {
142	        return None;
143	    }
144	    let num: usize = line[..i].parse().ok()?;
145	    Some((num, i + 2))
146	}
147	
148	/// Finalize a pending entry: emit its corrected lines into `out`
149	/// and, when the number or continuation indent changed, push a
150	/// `Change`.
151	///
152	/// The continuation block is shifted as a whole by
153	/// `prefix_width - measured_base`, so a deliberately nested
154	/// sub-bullet keeps its depth relative to the entry's base.
155	fn finish_entry(p: PendingEntry, changes: &mut Vec<Change>, out: &mut Vec<String>) {
156	    let prefix_width = digit_count(p.num_new) + 2; // ". " is two chars
157	    let new_first_line = format!("{}. {}", p.num_new, p.rest);
158	
159	    // Measured base = minimum indent of the *indented* non-blank
160	    // continuation lines. A column-0 line can't be a real list
161	    // continuation (continuations must be indented), so it's
162	    // excluded from the base and emitted verbatim below: a stray
163	    // one doesn't drag the base down to 0.
164	    let base = p
165	        .cont
166	        .iter()
167	        .filter(|l| !l.trim().is_empty())
168	        .map(|l| leading_spaces(l))
169	        .filter(|&n| n > 0)
170	        .min();
171	    let (indent_old, indent_new) = match base {
172	        Some(b) => (Some(b), Some(prefix_width)),
173	        None => (None, None),
174	    };
175	
176	    out.push(new_first_line.clone());
177	    let delta: isize = base.map_or(0, |b| prefix_width as isize - b as isize);
178	    for line in &p.cont {
179	        let indent = leading_spaces(line);
180	        if line.trim().is_empty() || indent == 0 {
181	            // Blank line, or a column-0 line that isn't a real
182	            // continuation, pass through unchanged.
183	            out.push(line.clone());
184	        } else {
185	            let shifted = (indent as isize + delta).max(0) as usize;
186	            out.push(format!(
187	                "{}{}",
188	                " ".repeat(shifted),
189	                line.trim_start_matches(' ')
190	            ));
191	        }
192	    }
193	
194	    if p.num_old != p.num_new || indent_old != indent_new {
195	        changes.push(Change {
196	            section: p.section,
197	            line_no: p.line_no,
198	            new_first_line,
199	            num_old: p.num_old,
200	            num_new: p.num_new,
201	            indent_old,
202	            indent_new,
203	        });
204	    }
205	}
206	
207	/// Scan a todo file's `## Todo` and `## Bugs` sections.
208	///
209	/// - Walks lines once, tracking the current `## ` section and the
210	///   entry being accumulated.
211	/// - An entry first-line is `N. ` at column 0; expected numbering
212	///   is `1..N` in document order.
213	/// - Any heading (`#`, `###`, ...) ends the current entry's
214	///   continuation block; `## Todo` / `## Bugs` headers also reset
215	///   the section.
216	/// - Returns one `Change` per off entry plus `fixed`, the file
217	///   content with every entry renumbered and re-indented. `fixed`
218	///   round-trips an already-correct file unchanged.
219	pub fn analyze(content: &str) -> Analysis {
220	    let mut changes = Vec::new();
221	    let mut out: Vec<String> = Vec::new();
222	    let mut todo_count = 0;
223	    let mut bugs_count = 0;
224	    let mut section: Option<Section> = None;
225	    let mut entry_idx = 0usize;
226	    let mut pending: Option<PendingEntry> = None;
227	
228	    // `split('\n')` (not `lines()`) so a trailing newline survives
229	    // the join below and `fixed` round-trips byte-for-byte.
230	    for (i, line) in content.split('\n').enumerate() {
231	        if let Some(kind) = section_header(line) {
232	            // A new ## section: finish the pending entry, switch.
233	            if let Some(p) = pending.take() {
234	                finish_entry(p, &mut changes, &mut out);
235	            }
236	            section = kind;
237	            entry_idx = 0;
238	            out.push(line.to_string());
239	            continue;
240	        }
241	        // Any other heading (`#`, `###`, ...) ends the current
242	        // entry's continuation block without changing the section.
243	        if line.starts_with('#') {
244	            if let Some(p) = pending.take() {
245	                finish_entry(p, &mut changes, &mut out);
246	            }
247	            out.push(line.to_string());
248	            continue;
249	        }
250	        let Some(sec) = section else {
251	            // Not inside a ## Todo / ## Bugs section.
252	            out.push(line.to_string());
253	            continue;
254	        };
255	        if let Some((num, prefix_len)) = parse_entry_prefix(line) {
256	            // A new entry: finish the previous one we were on.
257	            if let Some(p) = pending.take() {
258	                finish_entry(p, &mut changes, &mut out);
259	            }
260	            entry_idx += 1;
261	            match sec {
262	                Section::Todo => todo_count += 1,
263	                Section::Bugs => bugs_count += 1,
264	            }
265	            pending = Some(PendingEntry {
266	                section: sec,
267	                line_no: i + 1,
268	                num_old: num,
269	                num_new: entry_idx,
270	                rest: line[prefix_len..].to_string(),
271	                cont: Vec::new(),
272	            });
273	        } else if let Some(p) = pending.as_mut() {
274	            // Append the line of the current entry.
275	            p.cont.push(line.to_string());
276	        } else {
277	            // Section intro text before the first entry.
278	            out.push(line.to_string());
279	        }
280	    }
281	    // End of file: finish any entry still open.
282	    if let Some(p) = pending.take() {
283	        finish_entry(p, &mut changes, &mut out);
284	    }
285	
286	    Analysis {
287	        todo_count,
288	        bugs_count,
289	        changes,
290	        fixed: out.join("\n"),
291	    }
292	}
293	
294	#[cfg(test)]
295	mod tests {
296	    use super::*;
297	
298	    /// A correctly-numbered, correctly-indented file: no changes,
299	    /// and `fixed` round-trips it byte-for-byte.
300	    #[test]
301	    fn clean_file_has_no_changes() {
302	        let doc = "# Todo\n\n## Todo\n\n intro\n\n1. First.\n   cont.\n2. Second.\n3. \
303	              Third.\n   more.\n\n## Bugs\n\n bugs intro\n\n1. A bug.\n";
304	        let a = analyze(doc);
305	        assert_eq!(a.todo_count, 3);
306	        assert_eq!(a.bugs_count, 1);
307	        assert!(a.changes.is_empty());
308	        assert_eq!(a.fixed, doc);
309	    }
310	
311	    /// Entries numbered 2, 3 renumber to 1, 2.
312	    #[test]
313	    fn gap_renumbers() {
314	        let a = analyze("## Todo\n\n2. a.\n3. b.\n");
315	        assert_eq!(a.changes.len(), 2);
316	        assert_eq!((a.changes[0].num_old, a.changes[0].num_new), (2, 1));
317	        assert_eq!(a.changes[0].new_first_line, "1. a.");
318	        assert_eq!(a.changes[0].line_no, 3);
319	        assert_eq!((a.changes[1].num_old, a.changes[1].num_new), (3, 2));
320	        assert_eq!(a.fixed, "## Todo\n\n1. a.\n2. b.\n");
321	    }
322	
323	    /// A two-digit entry renumbered to one digit shifts its
324	    /// continuation indent 4 -> 3.
325	    #[test]
326	    fn indent_shifts_with_prefix_width() {
327	        let a = analyze("## Todo\n\n10. x.\n    cont.\n");
328	        assert_eq!(a.changes.len(), 1);
329	        let c = &a.changes[0];
330	        assert_eq!((c.num_old, c.num_new), (10, 1));
331	        assert_eq!((c.indent_old, c.indent_new), (Some(4), Some(3)));
332	        assert_eq!(a.fixed, "## Todo\n\n1. x.\n   cont.\n");
333	    }
334	
335	    /// A correctly-numbered entry with the wrong continuation
336	    /// indent is still flagged and rewritten.
337	    #[test]
338	    fn indent_only_issue_flagged() {
339	        let a = analyze("## Todo\n\n1. x.\n  cont.\n");
340	        assert_eq!(a.changes.len(), 1);
341	        let c = &a.changes[0];
342	        assert_eq!((c.num_old, c.num_new), (1, 1));
343	        assert_eq!((c.indent_old, c.indent_new), (Some(2), Some(3)));
344	        assert_eq!(a.fixed, "## Todo\n\n1. x.\n   cont.\n");
345	    }
346	
347	    /// Continuation indent is measured against the minimum (base)
348	    /// indent, so nested sub-bullets don't trip a correct entry.
349	    #[test]
350	    fn nested_sub_bullets_use_min_indent() {
351	        let a = analyze("## Todo\n\n1. x.\n   - sub.\n     deep.\n");
352	        assert!(a.changes.is_empty());
353	    }
354	
355	    /// When the base indent is off, the whole continuation block
356	    /// shifts together, nested depth is preserved, not flattened.
357	    #[test]
358	    fn nested_block_shifts_preserving_depth() {
359	        let a = analyze("## Todo\n\n1. x.\n  - sub.\n    deep.\n");
360	        assert_eq!(a.fixed, "## Todo\n\n1. x.\n   - sub.\n     deep.\n");
361	    }
362	
363	    /// `## Bugs` is numbered independently of `## Todo`.
364	    #[test]
365	    fn bugs_numbered_independently() {
366	        let a = analyze("## Todo\n\n1. t.\n\n## Bugs\n\n2. b.\n");
367	        assert_eq!(a.todo_count, 1);
368	        assert_eq!(a.bugs_count, 1);
369	        assert_eq!(a.changes.len(), 1);
370	        assert_eq!(a.changes[0].section, Section::Bugs);
371	        assert_eq!((a.changes[0].num_old, a.changes[0].num_new), (2, 1));
372	    }
373	
374	    /// A `### ` heading inside `## Todo` ends the prior entry and
375	    /// is not itself counted.
376	    #[test]
377	    fn heading_in_todo_section_ignored() {
378	        let a = analyze("## Todo\n\n intro\n\n### Current In Progress\n1. x.\n2. y.\n");
379	        assert_eq!(a.todo_count, 2);
380	        assert!(a.changes.is_empty());
381	    }
382	
383	    /// A column-0 `N. ` line in `## Done` is not scanned.
384	    #[test]
385	    fn done_section_not_scanned() {
386	        let a = analyze("## Todo\n\n1. x.\n\n## Done\n\n9. done thing\n");
387	        assert_eq!(a.todo_count, 1);
388	        assert!(a.changes.is_empty());
389	    }
390	
391	    /// Blank lines within an entry's continuation block carry no
392	    /// indent and don't affect the measured base.
393	    #[test]
394	    fn blank_continuation_lines_ignored() {
395	        let a = analyze("## Todo\n\n1. x.\n   cont.\n\n   more.\n2. y.\n");
396	        assert_eq!(a.todo_count, 2);
397	        assert!(a.changes.is_empty());
398	    }
399	
400	    /// `fixed` is a fixed point: re-running on it yields no
401	    /// further changes and identical content.
402	    #[test]
403	    fn fixed_is_idempotent() {
404	        let once = analyze("## Todo\n\n3. a.\n5. b.\n   c.\n").fixed;
405	        let twice = analyze(&once);
406	        assert!(twice.changes.is_empty());
407	        assert_eq!(twice.fixed, once);
408	    }
409	
410	    /// A stray column-0 line inside an entry's continuation block
411	    /// isn't a real continuation: it doesn't pull the measured
412	    /// base down, and it passes through verbatim.
413	    #[test]
414	    fn column_zero_line_is_not_a_continuation() {
415	        let doc = "## Todo\n\n1. x.\n   real cont.\n0\n   more cont.\n";
416	        let a = analyze(doc);
417	        assert!(a.changes.is_empty());
418	        assert_eq!(a.fixed, doc);
419	    }
420	
421	    /// Build a `Change` for `change_tag` tests.
422	    fn change(num_old: usize, num_new: usize, indent: Option<(usize, usize)>) -> Change {
423	        Change {
424	            section: Section::Todo,
425	            line_no: 1,
426	            new_first_line: String::new(),
427	            num_old,
428	            num_new,
429	            indent_old: indent.map(|(o, _)| o),
430	            indent_new: indent.map(|(_, n)| n),
431	        }
432	    }
433	
434	    /// A pure renumber tags the line number and old number.
435	    #[test]
436	    fn tag_number_only() {
437	        assert_eq!(change_tag(&change(3, 1, None)), "[1: was 3]");
438	    }
439	
440	    /// A pure re-indent tags the line number and indent shift.
441	    #[test]
442	    fn tag_indent_only() {
443	        assert_eq!(
444	            change_tag(&change(1, 1, Some((2, 3)))),
445	            "[1: indent 2 -> 3]"
446	        );
447	    }
448	
449	    /// A renumber that also shifts indent tags both.
450	    #[test]
451	    fn tag_number_and_indent() {
452	        assert_eq!(
453	            change_tag(&change(10, 9, Some((4, 3)))),
454	            "[1: was 10, indent 4 -> 3]"
455	        );
456	    }
457	}
458

