864	/// The body of `heading`'s section in `text`, as byte offsets: from
865	/// the line after the heading to the next `## ` or `# ` heading, else
866	/// the end. A heading inside a fenced code block is not one.
867	fn section(text: &str, heading: &str) -> Option<(usize, usize)> {
868	    let mut body = None;
869	    let mut fenced = false;
870	    let mut at = 0;
871	    for line in text.split_inclusive('\n') {
872	        let bare = line.trim_end_matches(['\n', '\r']);
873	        if bare.starts_with("```") {
874	            fenced = !fenced;
875	        } else if !fenced {
876	            if body.is_none() && bare == heading {
877	                body = Some(at + line.len());
878	            } else if let Some(start) = body
879	                && (bare.starts_with("## ") || bare.starts_with("# "))
880	            {
881	                return Some((start, at));
882	            }
883	        }
884	        at += line.len();
885	    }
886	    body.map(|start| (start, text.len()))
887	}
