1082	/// Push what was committed, as `vc-x1 push` would after it, when the
1083	/// commit asks: the bookmark advanced, or the line's when none was,
1084	/// and with `dry` the push's dry run, so a dry run shows it too. A
1085	/// draft below `@-` is kept local, since push publishes `@-`.
1086	fn push_after(
1087	    ctx: &mut Context,
1088	    repo: &Path,
1089	    publish: Publish,
1090	    bookmark: Option<&str>,
1091	    params: &CommitParams,
1092	    dry: bool,
1093	    land: Option<&LandPlan>,
1094	) -> Result<(), Box<dyn std::error::Error>> {
1095	    if let Some(land) = land {
1096	        return crate::land::run(ctx, repo, publish.scope(), land, "@-", "the closing", dry);
1097	    }
1098	    if params.closing.is_some() && bookmark.is_none() {
1099	        info!(
1100	            "commit: the closing carries no bookmark, and a push would publish it on the line's \
1101	             nearest, the target, so it is kept local: --land lands it"
1102	        );
1103	        return Ok(());
1104	    }
1105	    if let Some(rev) = &params.rev
1106	        && !jj::matches(repo, &format!("({rev}) & (@ | @-)"))?
1107	    {
1108	        info!(
1109	            "commit: '{rev}' is below @-, which push publishes, so it is kept local: `vc-x1 push` \
1110	             publishes it once it takes a revision"
1111	        );
1112	        return Ok(());
1113	    }
1114	    if !params.push {
1115	        info!("commit: kept local, `vc-x1 push` publishes it");
1116	        return Ok(());
1117	    }
1118	    let scope = publish.scope();
1119	    info!("commit: push what was committed");
1120	    crate::push::push(
1121	        ctx,
1122	        &crate::push::PushParams {
1123	            revision: None,
1124	            bookmark: bookmark.map(str::to_string),
1125	            repo: Some(repo.to_path_buf()),
1126	            scope,
1127	            step: false,
1128	            dry_run: dry,
1129	            yes: true,
1130	            // A commit push is a fast-forward, so a forced one is a
1131	            // surprise, refused: `vc-x1 push` asks.
1132	            forced: crate::common::ForcedPush::Refuse,
1133	        },
1134	    )
1135	}
