1137	/// Commit the agent repo alone: its `@` with the title and body,
1138	/// then its `main` set to it and pushed when the commit pushes.
1139	/// Unpaired it carries no trailer, and an `@` that is a work commit's
1140	/// pending partner keeps its change id, so the work commit's trailer
1141	/// still resolves, and a warning says the back-trailer is missing.
1142	/// With `--covers` it carries one `ochid:` per work commit covered,
1143	/// the pair a cycle's rungs make with one agent commit.
1144	fn commit_agent(
1145	    ctx: &mut Context,
1146	    pair: &Pair,
1147	    params: &CommitParams,
1148	) -> Result<(), Box<dyn std::error::Error>> {
1149	    let agent = pair.agent.as_path();
1150	    preflight(agent, "agent", true)?;
1151	    let (text, _) = description(params, None)?;
1152	    let chid = jj::chid_of(agent, "@")?;
1153	    let covered = match &params.covers {
1154	        Some(revset) => Some(covered_chids(pair, revset, &chid)?),
1155	        None => None,
1156	    };
1157	    let text = match &covered {
1158	        Some(chids) => with_ochids(&text, orepo_for(&pair.work, !params.no_url_trailer)?, chids),
1159	        None => text,
1160	    };
1161	    if covered.is_none()
1162	        && let Some(work) = crate::pair::work_commit(pair)?
1163	        && let crate::pair::Partner::Pending(at) = crate::pair::partner(pair, &work)?
1164	    {
1165	        warn!(
1166	            "commit -s a: the agent @ {at} is the pending partner of the work commit {}, which \
1167	             names it, and this commit carries no trailer back to it",
1168	            work.chid
1169	        );
1170	    }
1171	    let push = params.push;
1172	    if params.dry_run {
1173	        info!(
1174	            "commit: [dry-run] the agent commit {chid}, in {}:\n{text}",
1175	            agent.display()
1176	        );
1177	        if push {
1178	            info!("commit: [dry-run] then set the agent main to it and push it");
1179	        }
1180	        return Ok(());
1181	    }
1182	    let snapshot = crate::pair::Snapshot::take(agent)?;
1183	    match &covered {
1184	        Some(chids) => info!(
1185	            "commit agent: {} -> @- {chid}, covering {} work commit(s)",
1186	            agent.display(),
1187	            chids.len()
1188	        ),
1189	        None => info!("commit agent: {} -> @- {chid}, unpaired", agent.display()),
1190	    }
1191	    if let Err(e) = ctx.session(agent)?.commit(&text) {
1192	        snapshot.restore("commit", e.as_ref());
1193	        return Err(e);
1194	    }
1195	    if !push {
1196	        info!("commit: kept local, `vc-x1 push -s a` publishes it");
1197	        return Ok(());
1198	    }
1199	    info!("commit agent: set main to @- and push it");
1200	    let session = ctx.session(agent)?;
1201	    session.bookmark_set("main", "@-")?;
1202	    session.git_push_bookmark("main", crate::jj::Force::Refuse)
1203	}
