1205	/// The change ids of the work commits `revset` names, oldest first,
1206	/// each refused unless its `ochid:` names `agent_at`, the change the
1207	/// agent commit is made from, so every link is one both sides agree on.
1208	fn covered_chids(
1209	    pair: &Pair,
1210	    revset: &str,
1211	    agent_at: &str,
1212	) -> Result<Vec<String>, Box<dyn std::error::Error>> {
1213	    let work = pair.work.as_path();
1214	    let cids = jj::cids_of(work, revset)?;
1215	    if cids.is_empty() {
1216	        return Err(format!("commit --covers: '{revset}' names no work commit").into());
1217	    }
1218	    let mut chids = Vec::new();
1219	    let mut strays = Vec::new();
1220	    for cid in &cids {
1221	        let chid = jj::chid_of(work, cid)?;
1222	        let names = extract_ochid_from_desc(&jj::desc_of(work, cid)?)
1223	            .is_some_and(|ochid| extract_bare_id(&ochid) == agent_at);
1224	        if names {
1225	            chids.push(chid);
1226	        } else {
1227	            strays.push(chid);
1228	        }
1229	    }
1230	    if !strays.is_empty() {
1231	        return Err(format!(
1232	            "commit --covers: {} in '{revset}' do not name the agent @ {agent_at}, so the agent \
1233	             commit cannot cover them: {}",
1234	            strays.len(),
1235	            strays.join(", ")
1236	        )
1237	        .into());
1238	    }
1239	    Ok(chids)
1240	}
