1242	/// What `--closing` does, decided before anything is made.
1243	#[derive(Debug)]
1244	enum ClosingPlan {
1245	    /// A branch of one commit above `REV`, the opening: a single-step
1246	    /// cycle, its one commit finalized in place under the bare cycle
1247	    /// title, with the body given or else the opening's own.
1248	    Finalize { title: String, body: Option<String> },
1249	    /// A longer branch: the closing commit, the merge of `base` and
1250	    /// the last rung `tip`.
1251	    Merge {
1252	        base: String,
1253	        tip: String,
1254	        title: String,
1255	        body: String,
1256	    },
1257	    /// A branch with nothing committed above the target, its work in
1258	    /// `@` and `bookmark`, `vc-x1 open`'s, on it: a single-step cycle
1259	    /// whose one commit is made now from `@`, under the bare cycle
1260	    /// title and the body given, there being no opening to read.
1261	    Commit { bookmark: String },
1262	}
