1264	/// The bookmark a closing merges onto and a Land lands on, `--onto`'s,
1265	/// required: no target is assumed, since a bookmark made is only
1266	/// likely the one a cycle lands on. Left out, it is refused naming the
1267	/// likely one, the nearest bookmark at or below the opening's parent,
1268	/// the opening being the nearest commit below `tip` titled so.
1269	fn onto(repo: &Path, closing: &Closing, tip: &str) -> Result<String, Box<dyn std::error::Error>> {
1270	    if let Some(o) = &closing.onto {
1271	        return Ok(o.clone());
1272	    }
1273	    let opening = format!("heads(::({tip}) & description(regex:\"^[^\\n]* opening(\\n|$)\"))");
1274	    let likely = jj::local_bookmarks_at(repo, &format!("heads(::(({opening})-) & bookmarks())"))?;
1275	    let hint = match likely.as_slice() {
1276	        [] => String::new(),
1277	        [one] => format!(", likely `--onto {one}`"),
1278	        many => format!(", likely one of {}", many.join(", ")),
1279	    };
1280	    Err(format!(
1281	        "commit --closing: name the bookmark the cycle closes onto, --onto <BOOKMARK>{hint}"
1282	    )
1283	    .into())
1284	}
