1286	/// Plan `--closing`, refusing before anything is made. The argument
1287	/// names the tip, exactly one commit, and the target is `--onto`'s,
1288	/// read where it is now. The commits between decide the shape: none
1289	/// is refused, one, the opening, is a single-step cycle finalized in
1290	/// place, unless `--dead-end`, and more get the closing commit, the
1291	/// target and the tip its parents. The count reads the branch rather
1292	/// than a flag choosing the shape.
1293	fn plan_closing(
1294	    repo: &Path,
1295	    params: &CommitParams,
1296	) -> Result<Option<ClosingPlan>, Box<dyn std::error::Error>> {
1297	    let Some(c) = &params.closing else {
1298	        return Ok(None);
1299	    };
1300	    let rev = &c.rev;
1301	    let tip = resolve_closing(repo, rev)?;
1302	    let target = onto(repo, c, &tip)?;
1303	    let base = jj::cid_of(repo, &target).map_err(|e| {
1304	        format!(
1305	            "commit --closing: --onto '{target}' does not resolve in {}: {e}",
1306	            repo.display()
1307	        )
1308	    })?;
1309	    info!("commit --closing: close '{rev}' at {tip} onto '{target}' at {base}");
1310	    if let Some(plan) = plan_commit_closing(repo, params, c, &tip, &base, &target)? {
1311	        return Ok(Some(plan));
1312	    }
1313	    if tip == jj::cid_of(repo, "@")? {
1314	        return Err(format!(
1315	            "commit --closing: '{rev}' is the work @, which a closing commits only when the branch \
1316	             has nothing committed above '{target}': name the branch's last commit, @- the common \
1317	             one"
1318	        )
1319	        .into());
1320	    }
1321	    let nodes = jj::cids_of(repo, &format!("{base}..{tip}"))?;
1322	    if nodes.is_empty() {
1323	        return Err(format!(
1324	            "commit --closing: nothing above '{target}' to close, '{rev}' being in ::{target}: a \
1325	             cycle starts with `commit --opening`"
1326	        )
1327	        .into());
1328	    }
1329	    let cycle = match &params.title {
1330	        Some(t) => t.trim_end().to_string(),
1331	        None => cycle_title(repo, &base, &tip, &target)?,
1332	    };
1333	    if nodes.len() == 1 && !c.dead_end {
1334	        info!(
1335	            "commit --closing: one commit above '{target}', a single-step cycle, finalized in \
1336	             place as '{cycle}'"
1337	        );
1338	        return Ok(Some(ClosingPlan::Finalize {
1339	            title: cycle,
1340	            body: params.body.clone(),
1341	        }));
1342	    }
1343	    let suffix = if c.dead_end {
1344	        " dead-end closing"
1345	    } else {
1346	        " closing"
1347	    };
1348	    let body = match &params.body {
1349	        Some(b) => b.clone(),
1350	        None => default_body(repo, &cycle)?,
1351	    };
1352	    info!(
1353	        "commit --closing: {} commits above '{target}', so the closing commit merges it and \
1354	         '{rev}'",
1355	        nodes.len()
1356	    );
1357	    Ok(Some(ClosingPlan::Merge {
1358	        base,
1359	        tip,
1360	        title: format!("{cycle}{suffix}"),
1361	        body,
1362	    }))
1363	}
