1365	/// The closing of a branch with nothing committed above the target,
1366	/// the single-step cycle `vc-x1 open` leaves: the tip is the work `@`,
1367	/// named by its bookmark or `@`, or the target itself at `@-`, and
1368	/// `@-` is the target, so the cycle's one commit is made now from `@`.
1369	/// `None` when the branch has commits, the other shapes' case. Refused
1370	/// before anything is made: an empty `@`, no bookmark on `@` or several
1371	/// with none named, `--dead-end`, which closes a cycle with commits,
1372	/// and a title or body left out, there being no opening to read.
1373	fn plan_commit_closing(
1374	    repo: &Path,
1375	    params: &CommitParams,
1376	    c: &Closing,
1377	    tip: &str,
1378	    base: &str,
1379	    target: &str,
1380	) -> Result<Option<ClosingPlan>, Box<dyn std::error::Error>> {
1381	    let at = jj::cid_of(repo, "@")?;
1382	    let below = jj::cid_of(repo, "@-")?;
1383	    if !(tip == at || tip == below) || below != base {
1384	        return Ok(None);
1385	    }
1386	    let label = "commit --closing";
1387	    if jj::is_empty(repo, "@")? {
1388	        return Err(format!(
1389	            "{label}: nothing above '{target}' to close, '{}' having no commit above it and \
1390	             nothing to commit: a cycle starts with `vc-x1 open`",
1391	            c.rev
1392	        )
1393	        .into());
1394	    }
1395	    let mut on_at = jj::local_bookmarks_at(repo, "@")?;
1396	    on_at.retain(|b| b != target);
1397	    let bookmark = match on_at.as_slice() {
1398	        [] => {
1399	            return Err(format!(
1400	                "{label}: the work @ carries no bookmark, and a cycle runs on one: make it \
1401	                 first, `vc-x1 open --title \"<cycle title>\"`"
1402	            )
1403	            .into());
1404	        }
1405	        [one] => one.clone(),
1406	        many if many.contains(&c.rev) => c.rev.clone(),
1407	        many => {
1408	            return Err(format!(
1409	                "{label}: the work @ carries several bookmarks, {}, so name the cycle's, \
1410	                 --closing <BOOKMARK>",
1411	                many.join(", ")
1412	            )
1413	            .into());
1414	        }
1415	    };
1416	    if c.dead_end {
1417	        return Err(format!(
1418	            "{label} --dead-end: the branch has no commit above '{target}', and a dead end \
1419	             closes the commits a cycle made"
1420	        )
1421	        .into());
1422	    }
1423	    if params.title.is_none() || params.body.is_none() {
1424	        return Err(format!(
1425	            "{label}: the branch has no commit above '{target}', so its one commit is made now \
1426	             from the work @, and --title and --body are required, there being no opening to \
1427	             read them from"
1428	        )
1429	        .into());
1430	    }
1431	    info!(
1432	        "{label}: no commit above '{target}', a single-step cycle on '{bookmark}', its one \
1433	         commit made now from the work @"
1434	    );
1435	    Ok(Some(ClosingPlan::Commit { bookmark }))
1436	}
