1444	/// The cycle title read from the opening, the first commit above
1445	/// `base` on the way to `tip`, its " opening" removed. Refused when
1446	/// the branch has no one first commit or it is not an opening, asking
1447	/// for `--title`.
1448	fn cycle_title(
1449	    repo: &Path,
1450	    base: &str,
1451	    tip: &str,
1452	    target: &str,
1453	) -> Result<String, Box<dyn std::error::Error>> {
1454	    let roots = jj::cids_of(repo, &format!("roots({base}..{tip})"))?;
1455	    let [root] = roots.as_slice() else {
1456	        return Err(format!(
1457	            "commit --closing: the branch above '{target}' has {} first commits, so there is no \
