1459	            roots.len()
1460	        )
1461	        .into());
1462	    };
1463	    let desc = jj::desc_of(repo, root)?;
1464	    let first = desc.lines().next().unwrap_or_default().trim_end();
1465	    match first.strip_suffix(" opening") {
1466	        Some(cycle) => {
1467	            info!("commit --closing: the cycle is '{cycle}', read from the opening");
1468	            Ok(cycle.to_string())
1469	        }
1470	        None => Err(format!(
1471	            "commit --closing: the first commit above '{target}', '{first}', is not an opening, \
1472	             so the cycle title cannot be read from it: pass --title"
1473	        )
1474	        .into()),
1475	    }
1476	}
