1562	/// Finalize a single-step cycle's one commit in place: fold the work
1563	/// `@` into it and give it the bare cycle title, its body the one
1564	/// given or else its own, its trailer kept, so its change id and its
1565	/// partner stand. The agent `@` is left for push, which commits or
1566	/// folds it as the partner. The line's bookmark follows the rewrite.
1567	fn finalize(
1568	    ctx: &mut Context,
1569	    repo: &Path,
1570	    pair: Option<&Pair>,
1571	    title: &str,
1572	    body: Option<&str>,
1573	    dry_run: bool,
1574	) -> Result<(), Box<dyn std::error::Error>> {
1575	    preflight(repo, "work", false)?;
1576	    let trailers = match pair {
1577	        // An older commit's `ocid:` and `pcid:` give way to `orepo:`.
1578	        Some(pair) => match crate::pair::work_commit(pair)? {
1579	            Some(wc) => Some(Trailers {
1580	                orepo: match wc.trailers.orepo {
1581	                    Some(orepo) => Some(orepo),
1582	                    None => repo_url_for(&pair.agent)?,
1583	                },
1584	                ..wc.trailers
1585	            }),
1586	            None => {
1587	                return Err(
1588	                    "commit --closing: the work @- carries no `ochid:` trailer, so it \
1589	                            is not a pair's commit to finalize"
1590	                        .into(),
1591	                );
1592	            }
1593	        },
1594	        None => None,
1595	    };
1596	    let body = match body {
1597	        Some(b) => b.to_string(),
1598	        None => opening_body(repo)?,
1599	    };
1600	    let text = format!("{title}\n\n{body}");
