pub fn resolve_pair(repo: Option<&Path>) -> Result<Pair, Box<dyn std::error::Error>> {
    let both = RepoScope::Sides(Scope(vec![Side::Work, Side::Bot]));
    let repos = crate::common::resolve_scoped_repos(&both, repo)?;
    match repos.as_slice() {
