    ctx: &mut Context,
    repo: &Path,
    target: &str,
    sources: &[String],
    who: &str,
) -> Result<String, Box<dyn std::error::Error>> {
    let refs: Vec<&str> = sources.iter().map(String::as_str).collect();
    let new_id = ctx.session(repo)?.reparent(target, &refs)?;
    if jj::matches(repo, &format!("{new_id} & conflicts()"))? {
