/// The checks a Land makes of its destination, made before a closing
/// that a Land follows: `dest` is a local bookmark where its `origin`
/// is, and `tip`, when given, descends from it, each refusal naming
/// the ways on.
fn land_checks(
    work: &std::path::Path,
