    tip: Option<&str>,
) -> Result<(), Box<dyn std::error::Error>> {
    if !jj::local_bookmark_exists(work, dest)? {
        return Err(format!(
            "cycle --land: '{dest}' is not a local bookmark, and a Land moves one"
        )
        .into());
    }
