        assert_eq!(title_of(&fx.work, "main"), "feat: a cycle");
        assert_eq!(cid(&fx.work, "main@origin"), cid(&fx.work, "main"), "published");
        assert_eq!(cid(&fx.bot, "main@origin"), cid(&fx.bot, "main"), "the agent repo too");
    }

